package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_prepend_TriageGen1Test {

    @Test
    public void testPrepend_ValidHtml_AddsAtBeginning() {
        Element parent = new Element("div", "");
        parent.append("<span>Existing</span>");

        String newHtml = "<p>New</p><b>Bold</b>";
        parent.prepend(newHtml);

        // The implementation iterates through nodes in reverse order and calls prependChild.
        // For " <p>New</p><b>Bold</b> ", nodes are <p> and <b>.
        // Loop i=1: prependChild(<b>) -> parent: [<b>, <span>Existing</span>]
        // Loop i=0: prependChild(<p>) -> parent: [<p>, <b>, <span>Existing</span>]

        String expectedHtml = "<p>New</p><b>Bold</b><span>Existing</span>";
        Assert.assertEquals(expectedHtml, parent.html());
    }

    @Test
    public void testPrepend_WithTextNodes() {
        Element parent = new Element("div", "");
        parent.append("<span>Existing</span>");

        String newHtml = "Text<p>Para</p>";
        parent.prepend(newHtml);

        // Nodes: TextNode("Text"), <p>
        // Loop i=1: prependChild(<p>) -> [ <p>, TextNode, <span> ]
        // Loop i=0: prependChild(TextNode) -> [ TextNode, <p>, <span> ]

        String expectedHtml = "Text<p>Para</p><span>Existing</span>";
        Assert.assertEquals(expectedHtml, parent.html());
    }

    @Test
    public void testPrepend_EmptyHtml_DoesNothing() {
        Element parent = new Element("div", "");
        parent.append("<span>Existing</span>");

        parent.prepend("");

        Assert.assertEquals("<span>Existing</span>", parent.html());
    }

    @Test(expected = NullPointerException.class)
    public void testPrepend_NullHtml_ThrowsException() {
        Element parent = new Element("div", "");
        parent.prepend(null);
    }

    @Test
    public void testPrepend_ReturnsThis() {
        Element parent = new Element("div", "");
        Element returned = parent.prepend("<span></span>");

        Assert.assertSame(parent, returned);
    }

    @Test
    public void testPrepend_ComplexStructure() {
        Element parent = new Element("ul", "");
        parent.append("<li>Item 1</li>");

        String newHtml = "<li>New 1</li><li>New 2</li>";
        parent.prepend(newHtml);

        // Nodes: <li>New 1</li>, <li>New 2</li>
        // Loop i=1: prepend(New 2) -> [New 2, Item 1]
        // Loop i=0: prepend(New 1) -> [New 1, New 2, Item 1]

        String expectedHtml = "<li>New 1</li><li>New 2</li><li>Item 1</li>";
        Assert.assertEquals(expectedHtml, parent.html());
    }
}
